SELECT 14, 'medium', '[Zoho Interview PYQ] What is the exact output of this C code snippet involving pointer arithmetic?', '#include <stdio.h>
int main() {
    int arr[] = {10, 20, 30, 40};
    int *p = arr;
    *(p++) += 5;
    printf("%d %d", arr[0], *p);
    return 0;
}', 'c', '10 20', '15 20', '15 30', '10 30', 'B', 'In `*(p++) += 5`: the postfix `++` has higher precedence than `*`, but yields the original pointer `arr` for dereferencing before incrementing. Thus `arr[0]` becomes 10 + 5 = 15. After evaluation, `p` points to `arr[1]` (which is 20). Output is 15 20 (Option B).', 75, 'Zoho Interview PYQ', 1, 'verified_pyq', 'verified', 'Zoho', SHA1('[Zoho Interview PYQ] What is the exact output of this C code snippet involving pointer arithmetic?')
FROM `subtopics` s WHERE s.id = 14 AND NOT EXISTS (SELECT 1 FROM `questions` WHERE `question_text` = '[Zoho Interview PYQ] What is the exact output of this C code snippet involving pointer arithmetic?') LIMIT 1;

