SELECT 1, 'medium', '[UST Global PYQ] A train 125 meters long is traveling at 60 km/h. How many seconds will it take to completely pass a man walking at 6 km/h in the opposite direction?', NULL, 'quant', '6.8 seconds', '7.5 seconds', '8.2 seconds', '9.0 seconds', 'A', 'When moving in opposite directions, relative speed is the sum: 60 + 6 = 66 km/h. Convert to m/s: 66 * (5/18) = 110/6 = 55/3 m/s. Time to pass man = Distance / Speed = 125 / (55/3) = (125 * 3) / 55 = 375 / 55 = 6.818... ~ 6.8 seconds (Option A).', 65, 'UST Global PYQ', 1, 'verified_pyq', 'verified', 'UST', SHA1('[UST Global PYQ] A train 125 meters long is traveling at 60 km/h. How many seconds will it take to completely pass a man walking at 6 km/h in the opposite direction?')
FROM `subtopics` s WHERE s.id = 1 AND NOT EXISTS (SELECT 1 FROM `questions` WHERE `question_text` = '[UST Global PYQ] A train 125 meters long is traveling at 60 km/h. How many seconds will it take to completely pass a man walking at 6 km/h in the opposite direction?') LIMIT 1;

