SELECT 2, 'medium', '[HCL Tech PYQ] A container holds 40 liters of milk. From this container, 4 liters of milk are taken out and replaced by water. This process is repeated one more time. How much pure milk remains in the container?', NULL, 'quant', '32.4 liters', '33.6 liters', '31.2 liters', '30.0 liters', 'A', 'Formula for repeated replacement: Remaining liquid = Initial * (1 - x / V)^n. Here Initial = 40, x = 4, V = 40, n = 2. Remaining milk = 40 * (1 - 4/40)^2 = 40 * (0.9)^2 = 40 * 0.81 = 32.4 liters (Option A).', 60, 'HCL Tech PYQ', 1, 'verified_pyq', 'verified', 'HCL', SHA1('[HCL Tech PYQ] A container holds 40 liters of milk. From this container, 4 liters of milk are taken out and replaced by water. This process is repeated one more time. How much pure milk remains in the container?')
FROM `subtopics` s WHERE s.id = 2 AND NOT EXISTS (SELECT 1 FROM `questions` WHERE `question_text` = '[HCL Tech PYQ] A container holds 40 liters of milk. From this container, 4 liters of milk are taken out and replaced by water. This process is repeated one more time. How much pure milk remains in the container?') LIMIT 1;

