SELECT 14, 'medium', '[HCL Tech PYQ] In C, what is the correct syntax to declare a pointer to a function that takes two `int` parameters and returns a `double`?', NULL, 'c', 'double *func(int, int);', 'double (*func)(int, int);', 'double func*(int, int);', '(double*) func(int, int);', 'B', 'Parentheses around `(*func)` are required because function call `()` has higher precedence than dereference `*`. `double (*func)(int, int);` declares `func` as a pointer to a function returning double, whereas `double *func(int, int);` declares a function returning a pointer to double (Option B).', 55, 'HCL Tech PYQ', 1, 'verified_pyq', 'verified', 'HCL', SHA1('[HCL Tech PYQ] In C, what is the correct syntax to declare a pointer to a function that takes two `int` parameters and returns a `double`?')
FROM `subtopics` s WHERE s.id = 14 AND NOT EXISTS (SELECT 1 FROM `questions` WHERE `question_text` = '[HCL Tech PYQ] In C, what is the correct syntax to declare a pointer to a function that takes two `int` parameters and returns a `double`?') LIMIT 1;

